typedef enum { LIGHTS_OFF, LOW_BEAM, HIGH_BEAM, HIGH_BEAM_BLOCKED } BeamState;
typedef struct { bool low_beam_request; bool high_beam_request; bool auto_high_beam_enabled; bool oncoming_vehicle_detected; } Inputs;
typedef struct { bool low_beam; bool high_beam; } Outputs;
void update_state(BeamState *state, const Inputs *in) {
  switch (*state) {
    case LIGHTS_OFF:
      if (in->low_beam_request) *state = LOW_BEAM;
      break;
    case LOW_BEAM:
      if (!in->low_beam_request) *state = LIGHTS_OFF;
      else if (in->auto_high_beam_enabled && in->high_beam_request && in->oncoming_vehicle_detected) *state = HIGH_BEAM_BLOCKED;
      else if (in->auto_high_beam_enabled && in->high_beam_request) *state = HIGH_BEAM;
      break;
    case HIGH_BEAM:
      if (!in->low_beam_request) *state = LIGHTS_OFF;
      else if (!in->high_beam_request || !in->auto_high_beam_enabled) *state = LOW_BEAM;
      else if (in->oncoming_vehicle_detected) *state = HIGH_BEAM_BLOCKED;
      break;
    case HIGH_BEAM_BLOCKED:
      if (!in->low_beam_request) *state = LIGHTS_OFF;
      else if (!in->high_beam_request || !in->auto_high_beam_enabled) *state = LOW_BEAM;
      else if (!in->oncoming_vehicle_detected) *state = HIGH_BEAM;
      break;
  }
}
Outputs outputs_for(BeamState state) {
  Outputs out = { false, false };
  if (state == LOW_BEAM || state == HIGH_BEAM || state == HIGH_BEAM_BLOCKED) out.low_beam = true;
  if (state == HIGH_BEAM) out.high_beam = true;
  return out;
}
